-- ═══════════════════════════════════════════════════════════════════════════
--  0168 — Khalidiyah: FORM-09's participants, counted from tickets in one
--         table (Jordanians / Other by Men / Women / Children)
--
--  GENERATED by supabase/khalidiyah/gen_schema.py from the catalogue's
--  TICKET_ROWS, TICKET_COLS, TICKET_METHOD and `off` entries
--  (model.build(upto='0168') against '0167').
--
--  The municipality's owner asked on 28 September 2026 for the activity
--  participation form to count in one table -- columns Men, Women,
--  Children; rows Jordanians and Other; counting method Tickets -- with a
--  total, and for every percentage and every other estimate to go. Nothing
--  of it is in Khaldia_2_reviewed.xlsx; the wording is 06_OPEN_QUESTIONS.md
--  OQ-74.
--
--  ── F039 is the table ──
--
--  Six counts, one per cell, required, none negative. total_participants
--  (F039 since 0159, what D2 sums) is their sum, set by the database on
--  every save and held to it by a CHECK, so it is never typed and D2's view
--  reads it unchanged. The table holds no row today (asserted below), so the
--  six columns are NOT NULL from the start.
--
--  ── what leaves the form ──
--
--  F040-F044 and F133-F135 (the estimated percentages), F045 (nationalities,
--  a multi-select), F132 (the counting method) and F137 (its attendance
--  sheet). Their columns stay, blank from now on: the eight percentages are
--  held blank by a CHECK, so no estimate can reach a breakdown later; the
--  counting method stays NOT NULL and is set to Tickets on every save;
--  F045's rule row stays and requires nothing (khld_field_rule has no
--  deleted_at); F137's file field stays and is not asked. F136 (observed
--  interaction) is not a count and stays on the form.
--
--  ── the counting method ──
--
--  "Tickets" is added to ref_khld_counting_method and the sheet's three
--  (attendance sheet, head count, visual estimate) are made inactive --
--  retired, not deleted (a delete is a coordinator's act, guard_soft_delete).
--  No record uses them.
-- ═══════════════════════════════════════════════════════════════════════════

do $empty$
begin
  if exists (select 1 from public.khld_activity_attendance) then
    raise exception '0168 is written for an empty khld_activity_attendance: the six counts are NOT NULL';
  end if;
end $empty$;

-- ── 1. the six counts ─────────────────────────────────────────────────────
alter table public.khld_activity_attendance add column jordanian_men int not null;
comment on column public.khld_activity_attendance.jordanian_men is 'F039, Jordanians / Men: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add column jordanian_women int not null;
comment on column public.khld_activity_attendance.jordanian_women is 'F039, Jordanians / Women: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add column jordanian_children int not null;
comment on column public.khld_activity_attendance.jordanian_children is 'F039, Jordanians / Children: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add column other_men int not null;
comment on column public.khld_activity_attendance.other_men is 'F039, Other / Men: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add column other_women int not null;
comment on column public.khld_activity_attendance.other_women is 'F039, Other / Women: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add column other_children int not null;
comment on column public.khld_activity_attendance.other_children is 'F039, Other / Children: the participants counted from tickets (the owner''s request, 28 September 2026). 0168.';
alter table public.khld_activity_attendance add constraint khld_activity_attendance_tickets_not_negative
  check (jordanian_men >= 0 and jordanian_women >= 0 and jordanian_children >= 0 and other_men >= 0 and other_women >= 0 and other_children >= 0);
alter table public.khld_activity_attendance add constraint khld_activity_attendance_total_is_tickets
  check (total_participants = jordanian_men + jordanian_women + jordanian_children + other_men + other_women + other_children);

-- ── 2. the estimates, off the form and blank ──────────────────────────────
alter table public.khld_activity_attendance alter column pct_children drop not null;
alter table public.khld_activity_attendance alter column pct_adults drop not null;
alter table public.khld_activity_attendance alter column pct_male drop not null;
alter table public.khld_activity_attendance alter column pct_female drop not null;
alter table public.khld_activity_attendance alter column pct_disability drop not null;
alter table public.khld_activity_attendance alter column pct_youth drop not null;
alter table public.khld_activity_attendance alter column pct_jordanian drop not null;
alter table public.khld_activity_attendance alter column pct_syrian drop not null;
alter table public.khld_activity_attendance add constraint khld_activity_attendance_estimates_off_form
  check (pct_children is null and pct_adults is null and pct_male is null and pct_female is null and pct_disability is null and pct_youth is null and pct_jordanian is null and pct_syrian is null);

-- ── 3. the counting method: Tickets ───────────────────────────────────────
insert into public.ref_khld_counting_method (code, label_en, label_ar, sort_order, allows_free_text)
values ('tickets', 'Tickets', 'تذاكر', 4, false);
update public.ref_khld_counting_method set is_active = false where code <> 'tickets' and is_active;

-- ── 4. the total and the method, set on every save ────────────────────────
create function public.set_khld_attendance_from_tickets()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if num_nulls(new.jordanian_men, new.jordanian_women, new.jordanian_children, new.other_men, new.other_women, new.other_children) > 0 then
    raise exception 'F039: every cell of the ticket table is required'
      using errcode = 'check_violation', constraint = 'khld_f039_required';
  end if;
  new.total_participants := new.jordanian_men + new.jordanian_women + new.jordanian_children + new.other_men + new.other_women + new.other_children;
  select id into new.counting_method_id from public.ref_khld_counting_method where code = 'tickets' and is_active and deleted_at is null;
  return new;
end $$;
revoke all on function public.set_khld_attendance_from_tickets() from public, anon, authenticated;
comment on function public.set_khld_attendance_from_tickets() is
  'BEFORE INSERT OR UPDATE on khld_activity_attendance: F039 is the sum of the six ticket counts (a typed total is '
  'overwritten), and the counting method is Tickets. A blank cell refuses as khld_f039_required. 0168.';
create trigger trg_khld_activity_attendance_tickets before insert or update on public.khld_activity_attendance
  for each row execute function public.set_khld_attendance_from_tickets();

-- ── 5. F045's rule: stays, asks nothing ───────────────────────────────────
update public.khld_field_rule set column_name = 'option:f045', required = false, conditions = '[]', when_text = 'always'
 where table_name = 'khld_activity_attendance' and field_code = 'F045';

-- ── verification: the rows, and the table driven, discarded ───────────────
do $verify$
declare
  v_khld   uuid := (select id from public.municipality where code = 'KHLD');
  v_act    uuid;
  v_att    uuid;
  v_period text;
  v_before numeric;
  v_after  numeric;
  v_total  int;
  v_method text;
begin
  if (select count(*) from public.khld_field_rule) <> 37 then
    raise exception '0168: the rule rows are not the catalogue''s';
  end if;
  if (select count(*) from public.ref_khld_counting_method where is_active and deleted_at is null) <> 1
     or not exists (select 1 from public.ref_khld_counting_method where code = 'tickets' and is_active and deleted_at is null) then
    raise exception '0168: Tickets is not the one counting method';
  end if;

  begin
    insert into public.khld_activity (municipality_id, start_date, end_date, description, activity_type_id, target_audience_id,
                                      organiser_id, activity_name, status_id)
    values (v_khld, current_date, current_date, '0168 probe', (select id from public.ref_khld_activity_type order by sort_order limit 1),
            (select id from public.ref_khld_target_audience order by sort_order limit 1),
            (select id from public.ref_khld_organiser where code = 'municipality_alone'), '0168 probe activity',
            (select id from public.ref_khld_event_status where code = 'held'))
    returning id into v_act;
    select rp.code into v_period from public.reporting_period rp
     where rp.municipality_id = v_khld and current_date between rp.start_date and rp.end_date;
    select actual into v_before from public.v_ind_khld_d2 where municipality_id = v_khld and period_code = v_period;

    -- the six counts make the total, a typed total is overwritten, the method is Tickets
    insert into public.khld_activity_attendance (municipality_id, report_date, activity_id, total_participants, jordanian_men, jordanian_women, jordanian_children, other_men, other_women, other_children, observed_interaction_id)
    values (v_khld, current_date, v_act, 999, 1, 2, 3, 4, 5, 6, (select id from public.ref_khld_observed_interaction where code = 'none'))
    returning id into v_att;
    select a.total_participants, m.code into v_total, v_method
      from public.khld_activity_attendance a join public.ref_khld_counting_method m on m.id = a.counting_method_id
     where a.id = v_att;
    if v_total <> 21 or v_method <> 'tickets' then
      raise exception '0168: the total is %, the method %', v_total, v_method;
    end if;
    if v_period is not null then
      select actual into v_after from public.v_ind_khld_d2 where municipality_id = v_khld and period_code = v_period;
      if v_after is distinct from v_before + 21 then
        raise exception '0168: D2 moved from % to %, not by 21', v_before, v_after;
      end if;
    end if;
    -- an edit recomputes it
    update public.khld_activity_attendance set other_children = 16 where id = v_att;
    if (select total_participants from public.khld_activity_attendance where id = v_att) <> 31 then
      raise exception '0168: an edit did not recompute the total';
    end if;

    -- a blank cell, a negative count and an estimate are refused
    begin
      insert into public.khld_activity_attendance (municipality_id, report_date, activity_id, jordanian_men, jordanian_women, jordanian_children, other_men, other_women, other_children, observed_interaction_id)
      values (v_khld, current_date, v_act, 1, 2, 3, 4, 5, null, (select id from public.ref_khld_observed_interaction where code = 'none'));
      raise exception '0168: a blank cell was saved';
    exception when check_violation then
      if sqlerrm !~ '^F039: every cell' then raise; end if;
    end;
    begin
      insert into public.khld_activity_attendance (municipality_id, report_date, activity_id, jordanian_men, jordanian_women, jordanian_children, other_men, other_women, other_children, observed_interaction_id)
      values (v_khld, current_date, v_act, 1, 2, 3, 4, 5, -1, (select id from public.ref_khld_observed_interaction where code = 'none'));
      raise exception '0168: a negative count was saved';
    exception when check_violation then
      if sqlerrm !~ 'khld_activity_attendance_tickets_not_negative' then raise; end if;
    end;
    begin
      insert into public.khld_activity_attendance (municipality_id, report_date, activity_id, jordanian_men, jordanian_women, jordanian_children, other_men, other_women, other_children, observed_interaction_id, pct_children)
      values (v_khld, current_date, v_act, 1, 2, 3, 4, 5, 6, (select id from public.ref_khld_observed_interaction where code = 'none'), 50);
      raise exception '0168: an estimated percentage was saved';
    exception when check_violation then
      if sqlerrm !~ 'khld_activity_attendance_estimates_off_form' then raise; end if;
    end;
    raise exception using errcode = 'P0168', message = 'rollback the probes';
  exception when sqlstate 'P0168' then null;
  end;
  if exists (select 1 from public.khld_activity where activity_name = '0168 probe activity') or exists (select 1 from public.khld_activity_attendance) then
    raise exception '0168: probe rows survived the rollback';
  end if;
end $verify$;
